fn bump(v: i32, d: i32) -> i32 {
    let mut n: i32 = v + d;
    if n < 0 { n = 0; }
    if n > 20 { n = 20; }
    n
}

fn frame(t: i32) {
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(1);
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let mut v: i32 = host::display::state_get(0);
    let mut hold: i32 = host::display::state_get(2);
    let inminus: i32 = if px >= 40 && px < 92 && py >= 100 && py < 152 { 1 } else { 0 };
    let inplus: i32 = if px >= 220 && px < 272 && py >= 100 && py < 152 { 1 } else { 0 };
    if down == 1 && (inminus == 1 || inplus == 1) {
        let d: i32 = if inplus == 1 { 1 } else { -1 };
        if prev == 0 {
            v = bump(v, d);
            hold = 0;
        } else {
            hold = hold + 1;
            if hold > 30 && hold % 6 == 0 { v = bump(v, d); }
        }
        host::display::state_set(0, v);
    } else {
        hold = 0;
    }
    host::display::state_set(1, down);
    host::display::state_set(2, hold);
    host::display::clear(0x101010);
    host::display::fill_rect(40, 100, 52, 52, 0x303040);
    host::display::draw_string(60, 118, "-", 0xffffff, 3);
    host::display::fill_rect(220, 100, 52, 52, 0x303040);
    host::display::draw_string(238, 118, "+", 0xffffff, 3);
    host::display::draw_number(140, 112, v, 0x00ff88, 4);
    host::display::draw_string(40, 60, "QUANTITY 0 - 20", 0x808080, 1);
    host::display::present();
}
